class Solution {
public:
    long long maximumSumOfHeights(vector<int>& maxHeights) {
        int n = maxHeights.size();
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            long long curr = maxHeights[i];
            int h = maxHeights[i];
            for (int j = i - 1; j >= 0; j--) {
                h = min(h, maxHeights[j]);
                curr += h;
            }
            h = maxHeights[i];
            for (int j = i + 1; j < n; j++) {
                h = min(h, maxHeights[j]);
                curr += h;
            }
            ans = max(ans, curr);
        }
        return ans;
    }
};

class Solution {
    public long maximumSumOfHeights(List<Integer> maxHeights) {
        int n = maxHeights.size();
        long ans = 0;
        for (int i = 0; i < n; i++) {
            long curr = maxHeights.get(i);
            int h = maxHeights.get(i);
            for (int j = i - 1; j >= 0; j--) {
                h = Math.min(h, maxHeights.get(j));
                curr += h;
            }
            h = maxHeights.get(i);
            for (int j = i + 1; j < n; j++) {
                h = Math.min(h, maxHeights.get(j));
                curr += h;
            }
            ans = Math.max(ans, curr);
        }
        return ans;
    }
}

